/**
 * Registers a handler for one event type. Call the return value to detach.
 *
 * The handler set is copy-on-write: a subscribe or unsubscribe that happens
 * while `emit()` is walking its snapshot never mutates that collection.
 * Unsubscribe removes the handler from the set currently installed in the
 * map. Deleting from the set captured at subscribe time would leave the
 * handler live once a later subscribe for the same event replaced that set,
 * so a detach/re-attach cycle would stack duplicate listeners.
 */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const added: HandlerSet = new Set(handlers.get(type));
  added.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, added);
  return () => {
    const live = handlers.get(type);
    if (live === undefined || !live.has(handler as EventHandler<TaskflowEventType>)) {
      return;
    }
    const next: HandlerSet = new Set(live);
    next.delete(handler as EventHandler<TaskflowEventType>);
    handlers.set(type, next);
  };
}

