import { resetEventBus, subscriberCount, emit } from "@/lib/event-bus";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import type { IssueId, IsoTimestamp, ProjectId, UserId } from "@/types/common";

const payload = {
  orgId: "org" as never,
  actorId: "usr" as UserId,
  occurredAt: "2026-03-15T12:00:00.000Z" as IsoTimestamp,
  issueId: "iss" as IssueId,
  projectId: "prj" as ProjectId,
  title: "t",
  assigneeId: "usr" as UserId,
  priority: "medium" as const,
};

describe("detach/reattach", () => {
  afterAll(() => {
    unregisterEventHandlers();
    resetEventBus();
  });

  it("keeps one listener set across cycles and leaves notifications attached", async () => {
    const assigned = { calls: 0 };
    const { subscribe } = await import("@/lib/event-bus");
    // notification fan-out is already attached at import of event-registry
    const beforeAssigned = subscriberCount("issue.assigned");

    registerEventHandlers();
    registerEventHandlers();
    const created = subscriberCount("issue.created");
    const status = subscriberCount("issue.status_changed");
    const assignedAfter = subscriberCount("issue.assigned");
    expect(created).toBeGreaterThan(0);
    expect(assignedAfter).toBe(beforeAssigned + 1);

    unregisterEventHandlers();
    expect(subscriberCount("issue.created")).toBe(0);
    expect(subscriberCount("issue.status_changed")).toBe(0);
    expect(subscriberCount("issue.assigned")).toBe(beforeAssigned);

    for (let i = 0; i < 4; i++) {
      registerEventHandlers();
      unregisterEventHandlers();
    }
    registerEventHandlers();
    registerEventHandlers();
    expect(subscriberCount("issue.created")).toBe(created);
    expect(subscriberCount("issue.status_changed")).toBe(status);
    expect(subscriberCount("issue.assigned")).toBe(assignedAfter);

    const off = subscribe("issue.assigned", () => {
      assigned.calls += 1;
    });
    await emit("issue.assigned", {
      orgId: payload.orgId,
      actorId: payload.actorId,
      occurredAt: payload.occurredAt,
      issueId: payload.issueId,
      projectId: payload.projectId,
      assigneeId: payload.assigneeId,
      from: null,
    });
    off();
    expect(assigned.calls).toBe(1);
    expect(subscriberCount("issue.assigned")).toBe(assignedAfter);
  });
});
